// Escolha (#/) — task-first home (design V3Entrada). Entry is by TASK, never by profile.
// Always the home page: the last route is offered as a link, never auto-redirected.
// Source of truth: this .tsx file (Preact). escolha.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment } from "../../vendor/preact/preact.module.js";
import { buildHash, type RouteCtx } from "../../ds/router.js";
import { Badge, mount } from "../../ds/ui.js";
import { lastRouteLabel } from "../app.js";

const TASKS = [
  { path: "/explorar", verb: "Explorar o polo sul", line: "Ver o terreno e os locais de pouso.", bullets: ["Relevo real (LOLA) e locais numerados", "Luz do Sol e Terra à vista por local", "Cada cartão abre em Resposta → Por quê → Prova"], icon: "M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18zM3 12h18" },
  { path: "/comparar", verb: "Comparar locais de pouso", line: "Luz, escuridão e visibilidade da Terra lado a lado.", bullets: ["Uma resposta direta, regras à vista", "Mesma janela para todos os locais", "Comparação técnica com exportação"], icon: "M3 4h5v16H3zM10 4h5v16h-5zM17 4h4v16h-4z" },
  { path: "/aula", verb: "Dar uma aula", line: "Modo projetor e atividade guiada.", bullets: ["Uma pergunta por vez, resposta no fim", "Montar atividade com link para a turma", "Notas do professor separadas"], icon: "M3 6h18v11H3zM8 21h8M12 17v4" },
  { path: "/bordo", verb: "Acompanhar a missão", line: "Painel de bordo do módulo.", bullets: ["Energia, contato e vida", "Replanejar após atraso", "Selos de origem em cada número"], icon: "M3 5h18v12H3zM8 21h8M12 17v4" },
];

export function render(outlet: HTMLElement, ctx: RouteCtx): void {
  const q = { site: ctx.site, t: ctx.query.t, d: ctx.query.d };
  const last = lastRouteLabel();
  mount(outlet, <>
    <div class="escolha">
      <section class="hero">
        <span class="chipg">Lunar Landing Site Navigator · polo sul da Lua</span>
        <h1 class="title-xl" data-route-title="">O que você quer fazer hoje?</h1>
        <p class="t2">Todos usam a mesma ferramenta e os mesmos dados. A tarefa só muda por onde você começa.</p>
      </section>
      <p class="notice glass-in row"><Badge kind="sim" text="Protótipo" />Protótipo. Dados sintéticos quando indicado.</p>
      {last ? <a class="resume wpill" href={last.hash}>Continuar de onde parou →<span class="v">{last.label}</span></a> : null}
      <nav class="tasks" aria-label="Tarefas">{TASKS.map(t =>
        <a class="task glass" href={buildHash(t.path, q)}>
          <span class="ic"><svg viewBox="0 0 24 24" class="i" aria-hidden="true"><path d={t.icon} /></svg></span>
          <span class="verb">{t.verb}</span>
          <span class="t2">{t.line}</span>
          <ul>{t.bullets.map(b => <li>{b}</li>)}</ul>
          <span class="go"><span class="lbl-s">Abrir</span><span class="chipa" aria-hidden="true">→</span></span>
        </a>)}</nav>
      <div class="row wrap">
        <a class="chipg" href={buildHash("/evidencias", q)}>Ver fontes e limitações →</a>
        <a class="chipg" href={buildHash("/terreno", q)}>Ver a Lua em 3D (polo sul) →</a>
      </div>
      <p class="t3 small">O painel principal utiliza Lua 3D (imagens LRO, relevo LOLA, Sol pelo SPICE) e a prévia estática do mesmo relevo de Joel quando o 3D não está disponível. Uso ilustrativo, sem validação independente.</p>
    </div>
  </>);
}
